-- ============================================================================
-- Combat Tool (/combat): per-member combat profiles, saved setups, gear catalog
-- Depends on: auth.users, members
-- Gear catalog seeded from dungeon-tracker gear_items (legendary + mythic, CL 60+).
-- ============================================================================

CREATE TABLE IF NOT EXISTS gear_items (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  slot TEXT NOT NULL,
  quality TEXT NOT NULL,
  agility INT NOT NULL DEFAULT 0,
  accuracy INT NOT NULL DEFAULT 0,
  protection INT NOT NULL DEFAULT 0,
  attack_power INT NOT NULL DEFAULT 0,
  critical_damage INT NOT NULL DEFAULT 0,
  combat_level INT NOT NULL,
  tier_modifiers JSONB,
  max_tier INT,
  image_url TEXT,
  hashed_item_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_gear_items_slot ON gear_items(slot, combat_level);

-- One row per (website user, linked character). Snapshot = last API sync;
-- settings/gear = what the member entered (API exposes no gear combat stats).
CREATE TABLE IF NOT EXISTS combat_profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  member_id UUID REFERENCES members(id) ON DELETE SET NULL,
  hashed_id TEXT NOT NULL,
  ign TEXT NOT NULL,
  character_class TEXT,
  image_url TEXT,
  stats JSONB,
  equipped_pet JSONB,
  pets JSONB NOT NULL DEFAULT '[]'::jsonb,
  effects JSONB NOT NULL DEFAULT '[]'::jsonb,
  location JSONB,
  gear JSONB NOT NULL DEFAULT '[]'::jsonb,       -- [{slot, gear_item_id, tier}]
  settings JSONB NOT NULL DEFAULT '{}'::jsonb,   -- crit, guild slayer, HP, pet mastery/pat, manual adj
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  last_sync TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, hashed_id)
);
CREATE INDEX IF NOT EXISTS idx_combat_profiles_user ON combat_profiles(user_id);

-- Named sandboxes (replaces the HTML tool's localStorage tabs)
CREATE TABLE IF NOT EXISTS combat_setups (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  profile_id UUID REFERENCES combat_profiles(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_combat_setups_user ON combat_setups(user_id);

ALTER TABLE gear_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE combat_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE combat_setups ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "gear_items_read_all" ON gear_items;
CREATE POLICY "gear_items_read_all" ON gear_items FOR SELECT USING (TRUE);

DROP POLICY IF EXISTS "combat_profiles_own" ON combat_profiles;
CREATE POLICY "combat_profiles_own" ON combat_profiles
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "combat_setups_own" ON combat_setups;
CREATE POLICY "combat_setups_own" ON combat_setups
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- ============================================================================
-- Seed: gear_items
-- ============================================================================
ON CONFLICT (name) DO UPDATE SET
  slot = EXCLUDED.slot, quality = EXCLUDED.quality,
  agility = EXCLUDED.agility, accuracy = EXCLUDED.accuracy,
  protection = EXCLUDED.protection, attack_power = EXCLUDED.attack_power,
  critical_damage = EXCLUDED.critical_damage, combat_level = EXCLUDED.combat_level,
  tier_modifiers = EXCLUDED.tier_modifiers, max_tier = EXCLUDED.max_tier,
  image_url = EXCLUDED.image_url, hashed_item_id = EXCLUDED.hashed_item_id;
